package net.zartra.gui;
import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.entity.Player;import java.io.*;import java.util.*;
public final class ZGuiCommand implements CommandExecutor,TabCompleter {private final ZartraGUIPlugin p;private final MenuManager m;private final GuiEditor e;public ZGuiCommand(ZartraGUIPlugin p,MenuManager m,GuiEditor e){this.p=p;this.m=m;this.e=e;}private boolean allowed(CommandSender s,String n){return s.hasPermission("zartragui.admin")||s.hasPermission("zartragui."+n);}
 public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(a.length==0){if(!(s instanceof Player)){s.sendMessage("Players only.");return true;}if(!allowed(s,"edit")){s.sendMessage(Chat.color("&cNo permission."));return true;}e.main((Player)s);return true;}String sub=a[0].toLowerCase();if(sub.equals("help")){s.sendMessage("/zgui <create|edit|open|delete|list|reload>");return true;}if(sub.equals("list")){for(MenuDefinition d:m.all())s.sendMessage(d.id()+" - "+d.title());return true;}if(sub.equals("reload")){if(!allowed(s,"reload"))return no(s);p.reloadConfig();s.sendMessage("Reloaded config.");return true;}if(sub.equals("create")){if(!allowed(s,"create"))return no(s);if(a.length<2||!MenuManager.validId(a[1])||m.get(a[1])!=null){s.sendMessage("Invalid or existing menu ID.");return true;}MenuDefinition d=m.create(a[1]);try{m.save(d);s.sendMessage("Created "+d.id());}catch(IOException x){s.sendMessage("Save failed.");}return true;}if(a.length<2){s.sendMessage("Missing menu ID.");return true;}MenuDefinition d=m.get(a[1]);if(d==null){s.sendMessage("Unknown menu.");return true;}if(sub.equals("edit")){if(!allowed(s,"edit"))return no(s);if(s instanceof Player)e.editor((Player)s,d);return true;}if(sub.equals("open")){if(!allowed(s,"open"))return no(s);Player target=s instanceof Player?(Player)s:null;if(a.length>2){if(!allowed(s,"open.others"))return no(s);target=Bukkit.getPlayer(a[2]);}if(target==null){s.sendMessage("Player required/offline.");return true;}m.open(target,d);return true;}if(sub.equals("delete")){if(!allowed(s,"delete"))return no(s);m.delete(d.id());s.sendMessage("Deleted "+d.id());return true;}return false;}
 private boolean no(CommandSender s){s.sendMessage(Chat.color("&cNo permission."));return true;}public List<String> onTabComplete(CommandSender s,Command c,String l,String[] a){if(a.length==1)return prefix(Arrays.asList("create","edit","open","delete","list","reload","help"),a[0]);if(a.length==2&&!(a[0].equalsIgnoreCase("create")))return prefix(ids(),a[1]);return Collections.emptyList();}private List<String> ids(){List<String>x=new ArrayList<String>();for(MenuDefinition d:m.all())x.add(d.id());return x;}private List<String> prefix(List<String>x,String q){List<String>r=new ArrayList<String>();for(String v:x)if(v.startsWith(q.toLowerCase()))r.add(v);return r;}}
